Secondly, as a note for storing in the back of ones mind, so that anyone working on the collapsing strings routines might spot something in the code base that's wrong. (I'm following the bug, so would be able to re-test at that time, since I can't share the whole code base.)","timestamp":1333290013,"attachments":[]},{"id":6,"commenterId":659813697836453438,"content":"p.s. apologies for the 699 ref. I saw a collapsed string and jumped to the wrong conclusion.","timestamp":1333290104,"attachments":[]},{"id":7,"commenterId":659813697836453438,"content":"So I wrote those comments last night, but hadn't hit send :( I've since had a chance to prune down 6KLOC to 45. As below:

// ==ClosureCompiler==
// @compilation_level ADVANCED_OPTIMIZATIONS
// @output_file_name default.js
// @formatting pretty_print
// ==/ClosureCompiler==

/**
* @constructor
*/
sgxColorRGBA = function(r,g,b,a) {
	this.r = (r==undefined?1:r);
	this.g = (g==undefined?1:g);
	this.b = (b==undefined?1:b);
	this.a = (a==undefined?1:a);
}


sgxColorRGBA.prototype.asHex = function() {
	var hexString = "";
	
	str = (Math.floor(this.r*255)).toString(16);
	if (str.length < 2) { str = "0"+str; }
	hexString += str;

	str = (Math.floor(this.g*255)).toString(16);
	if (str.length < 2) { str = "0"+str; }
	hexString += str;

	str = (Math.floor(this.b*255)).toString(16);
	if (str.length < 2) { str = "0"+str; }
	hexString += str;

	str = (Math.floor(this.a*255)).toString(16);
	if (str.length < 2) { str = "0"+str; }
	hexString += str;

	return hexString;
}


var col = new sgxColorRGBA(0.2,0.3,0.4,1);
alert(col.asHex());

var col2 = new sgxColorRGBA(0.3,0.4,0.5,1);
alert(col2.asHex());


It's the second sgxColorRGBA invocation that triggers the bug. With only one, the crux is:

str = Math.floor(255 * b.d).toString(16);
2 > str.length && (str = "0" + str);
c += str;

With both, you get:

  str = Math.floor(255 * a.d).toString(16);
  2 > str.length && (str = "0" + str);
[note no c += str; here]

sgxFloor is/was a direct call to Math.floor and had no change on the results.

Hope this is better :)

